using Spec = std::function<bool(const Invoice&)>;

Spec overdue(int days) {
  return [days](const Invoice& i){ return i.days_past_due >= days; };
}
Spec And(Spec a, Spec b) { return [a, b](const Invoice& i){ return a(i) && b(i); }; }

auto collectable = And(overdue(30), [](const Invoice& i){ return !i.in_collection; });
std::ranges::copy_if(invoices, out, collectable);

template <class T> struct Spec {
  virtual bool operator()(const T&) const = 0;
  virtual ~Spec() = default;
};
template <class T> struct And : Spec<T> {
  std::vector<std::unique_ptr<Spec<T>>> parts;
  bool operator()(const T& c) const override {
    for (auto& p : parts) if (!(*p)(c)) return false;
    return true;
  }
};

